item.stdout:
plugins {
    id 'java'
    id 'org.springframework.boot' version '3.5.16'
}

group = 'com.example'
version = '0.1.0'

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

repositories {
    mavenCentral()
}

dependencies {
    implementation platform('org.springframework.boot:spring-boot-dependencies:3.5.16')
    implementation 'org.springframework.boot:spring-boot-starter-web'
    implementation 'org.springframework.boot:spring-boot-starter-validation'
    implementation 'org.springframework.boot:spring-boot-starter-jdbc'
    implementation 'org.springframework.boot:spring-boot-starter-actuator'
    runtimeOnly 'com.h2database:h2'
    runtimeOnly 'com.mysql:mysql-connector-j'
    testImplementation 'org.springframework.boot:spring-boot-starter-test'
    testRuntimeOnly 'org.junit.platform:junit-platform-launcher'
}

tasks.withType(JavaCompile).configureEach {
    options.encoding = 'UTF-8'
}

tasks.named('test') {
    useJUnitPlatform()
}

tasks.named('bootJar') {
    archiveFileName = 'app.jar'
}

tasks.named('jar') {
    enabled = false
}
org.gradle.caching=true
org.gradle.jvmargs=-Xmx1g -Dfile.encoding=UTF-8
org.gradle.daemon=false
rootProject.name = 'gitcangku1'
spring:
  application:
    name: gitcangku1
  config:
    import: "optional:configtree:/run/secrets/"
  datasource:
    url: ${DB_URL:jdbc:h2:mem:artifact_lock;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1}
    username: ${DB_USER:sa}
    password: ${DB_PASSWORD:}
    hikari:
      maximum-pool-size: 5
      minimum-idle: 1
      connection-timeout: 10000
      validation-timeout: 3000
  sql:
    init:
      mode: embedded
      encoding: UTF-8
  jackson:
    time-zone: Asia/Shanghai
  lifecycle:
    timeout-per-shutdown-phase: 20s

server:
  port: 8080
  shutdown: graceful
  error:
    include-message: never
    include-stacktrace: never

management:
  endpoints:
    web:
      exposure:
        include: health
  endpoint:
    health:
      show-details: never
-- 杞欢鍒跺搧渚濊禆閿佸畾锛欻2锛圡ODE=MySQL锛夊缓琛ㄨ剼鏈紝浠呭湪 JVM 鐢熷懡鍛ㄦ湡鍐呬繚鐣欐暟鎹€?
CREATE TABLE IF NOT EXISTS repository_state (
    id      BIGINT       NOT NULL PRIMARY KEY,
    version BIGINT       NOT NULL
);
COMMENT ON TABLE repository_state IS '鍗曡琛細浠撳簱鍏ㄥ眬鐗堟湰鍙凤紝鍒跺搧鐧昏鎴栨挙鍥炴椂鍔犱竴';
COMMENT ON COLUMN repository_state.version IS '浠撳簱鐗堟湰鍙凤紙鏃犵鍙烽暱鏁村瀷璇箟锛屽垵濮嬩负 0锛?;

CREATE TABLE IF NOT EXISTS artifact (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    name       VARCHAR(128) NOT NULL,
    version    INT          NOT NULL,
    withdrawn  TINYINT      NOT NULL DEFAULT 0,
    created_at TIMESTAMP(6) NOT NULL
);
COMMENT ON TABLE artifact IS '杞欢鍒跺搧鐗堟湰锛宯ame 涓?version 鑱斿悎鍞竴锛屾挙鍥炰笉鍒犻櫎';
COMMENT ON COLUMN artifact.name IS '鍒跺搧鍚嶇О';
COMMENT ON COLUMN artifact.version IS '鍒跺搧鐗堟湰鍙凤紝姝ｆ暣鏁?;
COMMENT ON COLUMN artifact.withdrawn IS '鎾ゅ洖鐘舵€侊細0=鏈夋晥锛?=宸叉挙鍥烇紙璁板綍淇濈暀锛?;
COMMENT ON COLUMN artifact.created_at IS '鐧昏鏃堕棿锛孶TC 鏃堕棿鎴?;

CREATE UNIQUE INDEX IF NOT EXISTS uk_artifact_name_version ON artifact (name, version);
CREATE INDEX IF NOT EXISTS idx_artifact_name ON artifact (name);

CREATE TABLE IF NOT EXISTS artifact_dependency (
    id              BIGINT AUTO_INCREMENT PRIMARY KEY,
    artifact_id     BIGINT       NOT NULL,
    name            VARCHAR(128) NOT NULL,
    minimum_version INT          NOT NULL,
    maximum_version INT          NOT NULL,
    CONSTRAINT fk_dep_artifact FOREIGN KEY (artifact_id) REFERENCES artifact (id)
);
COMMENT ON TABLE artifact_dependency IS '鍒跺搧澹版槑鐨勪緷璧栧尯闂达紙闂尯闂达級锛岀櫥璁板悗涓嶅彲鏀?;
COMMENT ON COLUMN artifact_dependency.artifact_id IS '鎵€灞炲埗鍝佺増鏈?ID';
COMMENT ON COLUMN artifact_dependency.name IS '渚濊禆鍒跺搧鍚嶇О锛屽悓涓€鍒跺搧鍐呭敮涓€';
COMMENT ON COLUMN artifact_dependency.minimum_version IS '渚濊禆鏈€浣庣増鏈紙鍚級锛屾鏁存暟';
COMMENT ON COLUMN artifact_dependency.maximum_version IS '渚濊禆鏈€楂樼増鏈紙鍚級锛屾鏁存暟';

CREATE UNIQUE INDEX IF NOT EXISTS uk_dep_artifact_name ON artifact_dependency (artifact_id, name);

CREATE TABLE IF NOT EXISTS lock_file (
    id                 BIGINT AUTO_INCREMENT PRIMARY KEY,
    root_name          VARCHAR(128) NOT NULL,
    root_version       INT          NOT NULL,
    repository_version BIGINT       NOT NULL,
    request_id         VARCHAR(64)  NOT NULL,
    created_at         TIMESTAMP(6) NOT NULL
);
COMMENT ON TABLE lock_file IS '閿佸畾鏂囦欢锛氫竴娆℃垚鍔熼攣瀹氱殑鏍广€佺簿纭緷璧栭泦鍚堝強璇诲彇鏃剁殑浠撳簱鐗堟湰';
COMMENT ON COLUMN lock_file.root_name IS '鏍瑰埗鍝佸悕绉帮紙绮剧‘鐗堟湰锛岄攣瀹氭椂鍥哄畾锛?;
COMMENT ON COLUMN lock_file.root_version IS '鏍瑰埗鍝佺増鏈彿锛屾鏁存暟';
COMMENT ON COLUMN lock_file.repository_version IS '閿佸畾鏃惰鍙栫殑浠撳簱鐗堟湰鍙?;
COMMENT ON COLUMN lock_file.request_id IS '瑙﹀彂閿佸畾鐨勫叏灞€鍞竴璇锋眰 ID';
COMMENT ON COLUMN lock_file.created_at IS '閿佸畾鐢熸垚鏃堕棿锛孶TC 鏃堕棿鎴?;

CREATE UNIQUE INDEX IF NOT EXISTS uk_lock_request ON lock_file (request_id);
CREATE INDEX IF NOT EXISTS idx_lock_root ON lock_file (root_name, root_version);

CREATE TABLE IF NOT EXISTS lock_file_entry (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    lock_file_id BIGINT       NOT NULL,
    name         VARCHAR(128) NOT NULL,
    version      INT          NOT NULL,
    CONSTRAINT fk_entry_lock FOREIGN KEY (lock_file_id) REFERENCES lock_file (id)
);
COMMENT ON TABLE lock_file_entry IS '閿佹枃浠朵腑鐨勭簿纭埗鍝佺増鏈紝姣忎釜鍚嶇О浠呬竴涓増鏈?;
COMMENT ON COLUMN lock_file_entry.lock_file_id IS '鎵€灞為攣鏂囦欢 ID';
COMMENT ON COLUMN lock_file_entry.name IS '琚攣瀹氬埗鍝佸悕绉?;
COMMENT ON COLUMN lock_file_entry.version IS '琚攣瀹氱殑绮剧‘鐗堟湰鍙凤紝姝ｆ暣鏁?;

CREATE UNIQUE INDEX IF NOT EXISTS uk_entry_lock_name ON lock_file_entry (lock_file_id, name);

CREATE TABLE IF NOT EXISTS idempotent_request (
    request_id     VARCHAR(64)  NOT NULL PRIMARY KEY,
    operation      VARCHAR(32)  NOT NULL,
    request_hash   VARCHAR(64)  NOT NULL,
    http_status    INT          NOT NULL,
    response_json  CHARACTER LARGE OBJECT NOT NULL,
    created_at     TIMESTAMP(6) NOT NULL
);
COMMENT ON TABLE idempotent_request IS '鍐欐搷浣滃箓绛夎褰曪紝浠呬繚瀛樻垚鍔熻姹傦紱澶辫触涓嶅崰閿?;
COMMENT ON COLUMN idempotent_request.request_id IS '瀹㈡埛绔彁渚涚殑鍏ㄥ眬鍞竴璇锋眰 ID';
COMMENT ON COLUMN idempotent_request.operation IS '鎿嶄綔绫诲瀷锛歊EGISTER_ARTIFACT/WITHDRAW_ARTIFACT/CREATE_LOCK';
COMMENT ON COLUMN idempotent_request.request_hash IS '瑙勮寖鍖栬姹傚弬鏁扮殑 SHA-256 鎽樿锛屽紓鍙傞噸鏀剧敤浜庡啿绐佸垽瀹?;
COMMENT ON COLUMN idempotent_request.http_status IS '鍘熸垚鍔熷搷搴?HTTP 鐘舵€佺爜';
COMMENT ON COLUMN idempotent_request.response_json IS '鍘熸垚鍔熷搷搴?JSON锛岄噸鏀炬椂鍘熸牱杩斿洖';
COMMENT ON COLUMN idempotent_request.created_at IS '棣栨鎴愬姛鎻愪氦鏃堕棿锛孶TC 鏃堕棿鎴?;
-- 鍒濆鍖栧崟琛屼粨搴撶増鏈彿锛氬垵濮嬬増鏈负 0锛涜剼鏈彲閲嶅鎵ц锛堟祴璇曞涓婁笅鏂囧叡鐢ㄥ悓鍚嶅唴瀛樺簱锛夈€?INSERT INTO repository_state (id, version)
SELECT 1, 0 WHERE NOT EXISTS (SELECT 1 FROM repository_state WHERE id = 1);
